def write_complete(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text.lstrip(), encoding="utf-8", newline="\n")
    ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    print(f"[OK] FULL REPLACEMENT: {path.resolve()}")


def validate() -> None:
    if str(ROOT) not in sys.path:
        sys.path.insert(0, str(ROOT))
    for relative_path, module_name, expected, symbols in UPSTREAM_CHECKS:
        path = ROOT / relative_path
        if not path.is_file():
            raise RuntimeError(f"Required certified file missing: {path}")
        module = importlib.import_module(module_name)
        for name, value in expected.items():
            actual = getattr(module, name, None)
            if actual != value:
                raise RuntimeError(
                    f"{module_name} {name} mismatch: expected {value!r}, got {actual!r}"
                )
        missing = [name for name in symbols if not hasattr(module, name)]
        if missing:
            raise RuntimeError(
                f"{module_name} missing symbols: " + ", ".join(missing)
            )


def main() -> int:
    print("=" * 48)
    print(" OML-068 INSTALLER")
    print(" CERTIFIED MARKET-BEHAVIOR CANDIDATE VALIDATION AND ADMISSION")
    print("=" * 48)
    print("[BOOT] Revision: CURRENT_REPOSITORY_EXACT_INTERFACE_ALIGNMENT")

    try:
        validate()
        print("[OK] Current repository interfaces verified")

        tracked = {}
        for relative_path, _, _, _ in UPSTREAM_CHECKS:
            path = ROOT / relative_path
            tracked[path] = path.read_bytes()

        write_complete(PRODUCTION, PRODUCTION_SOURCE)
        write_complete(TEST, TEST_SOURCE)

        export = "from ." + PRODUCTION.stem + " import *"
        current = INIT.read_text(encoding="utf-8") if INIT.exists() else ""
        if export not in current.splitlines():
            if current and not current.endswith("\n"):
                current += "\n"
            current += export + "\n"
            INIT.write_text(current, encoding="utf-8", newline="\n")
            print(f"[OK] PACKAGE UPDATED: {INIT.resolve()}")
        else:
            print(f"[OK] PACKAGE EXPORT PRESENT: {INIT.resolve()}")

        completed = subprocess.run(
            [sys.executable, str(TEST)],
            cwd=ROOT,
            check=False,
        )
        if completed.returncode:
            raise RuntimeError(
                f"OML-068 test failed with exit code {completed.returncode}"
            )

        for path, before in tracked.items():
            if path.read_bytes() != before:
                raise RuntimeError(f"Certified upstream changed: {path}")

        print("[PASS] Certified upstream files unchanged")
        print("[PASS] Deterministic hashes and replay guarantees preserved")
        print("[PASS] Oracle Terminal separation preserved")
        print("[PASS] Persistence remained disabled")
        print("[PASS] Learning updates remained disabled")
        print("[PASS] Runtime activation remained disabled")
        print("[PASS] Publication remained disabled")
        print("[PASS] Action authorization remained disabled")
        print("[PASS] Q Series execution remained disabled")
        print("[DONE] OML-068 INSTALLED")
        return 0
    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
